public interface ExchangeRateProvider {
    BigDecimal rate(String currency);
}

@Component
class ConfiguredExchangeRates implements ExchangeRateProvider {
    private final Map<String, BigDecimal> rates;

    ConfiguredExchangeRates(RateProperties properties) {
        this.rates = Map.copyOf(properties.rates());      // bất biến, không có override
    }

    public BigDecimal rate(String currency) { return rates.get(currency); }
}

@Component
class PriceConverter {
    private final ExchangeRateProvider rates;

    PriceConverter(ExchangeRateProvider rates) { this.rates = rates; }

    BigDecimal toVnd(BigDecimal usd) { return usd.multiply(rates.rate("USD")); }
}

class PriceConverterTest {
    @Test
    void convertsUsdToVnd() {
        ExchangeRateProvider fixed = currency -> new BigDecimal("25400");
        assertEquals(new BigDecimal("254000"), new PriceConverter(fixed).toVnd(new BigDecimal("10")));
    }
}
